package com.realstant.nativegame; public final class Vector3 { public float x,y,z; public Vector3(){} public Vector3(float a,float b,float c){x=a;y=b;z=c;} public Vector3 set(float a,float b,float c){x=a;y=b;z=c;return this;} public Vector3 add(Vector3 v){x+=v.x;y+=v.y;z+=v.z;return this;} public Vector3 mul(float s){x*=s;y*=s;z*=s;return this;} public float len(){return (float)Math.sqrt(x*x+y*y+z*z);} }
